{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_56254597646f6e55f9aaee68", "claim_ids": ["claim_665d0913ca3af08893bd8a6c", "claim_6ec7160bbfa5375b4ae11a5c"], "query_ids": ["q_445"], "claims": [{"claim_id": "claim_665d0913ca3af08893bd8a6c", "quote": "Automotive display modules without systems-on-chips (SoCs) are classified as standalone components under HTSUS 8528.59.25xx and currently", "url": "https://omdia.tech.informa.com/om135783/display-dynamics--may-2025-us-automotive-tariff-analysis-and-its-impact-on-automotive-displays", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "Automotive display modules without systems-on-chips (SoCs)", "hts_code": "8528.59.25xx"}}, {"claim_id": "claim_6ec7160bbfa5375b4ae11a5c", "quote": "Key HS Codes to watch: - 9013.80.90 – Certain display modules", "url": "https://microtipsusa.com/navigating-u-s-tariffs-understanding-monitoring-and-minimizing-risk-for-tft-lcd-display-imports-from-china", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "Certain display modules", "chapter_99_code": "9013.80.90"}}]}, {"pair_id": "conflict_85dcfb56cc78b56eb642ddf1", "claim_ids": ["claim_c735ea79ff1ccac4072fed3b", "claim_ec9e91e60338d9d0a0e7531f"], "query_ids": ["q_446"], "claims": [{"claim_id": "claim_c735ea79ff1ccac4072fed3b", "quote": "NY N306705, dated October 31, 2019, CBP classified LCD indicator panels for automobiles in heading 8531, HTSUS", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H325872&highlight=category%3AClassification", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "LCD indicator panels for automobiles", "hts_code": "8531, HTSUS", "announcement_date": "October 31, 2019"}}, {"claim_id": "claim_ec9e91e60338d9d0a0e7531f", "quote": "the subject LCD display module is classified in heading 8528, specifically subheading 8528.59.25, HTSUS", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H325872&highlight=category%3AClassification", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "LCD display module", "hts_code": "8528.59.25, HTSUS", "duty_rate": "free"}}]}, {"pair_id": "conflict_47b8e0e4dbfd50159bf8dc4b", "claim_ids": ["claim_a79d12636c8b91a8d8f5b549", "claim_f06e6eebac352f909c42817b"], "query_ids": ["q_447"], "claims": [{"claim_id": "claim_a79d12636c8b91a8d8f5b549", "quote": "President Trump imposed auto tariffs based on the findings of a 2019 investigation, which concluded that U.S. auto imports were a threat to U.S. national security.", "url": "https://www.congress.gov/crs-product/IN12545", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "findings of a 2019 investigation"}}, {"claim_id": "claim_f06e6eebac352f909c42817b", "quote": "In 2025, President Donald Trump imposed 25% tariffs on U.S. imports of automobiles and certain automobile parts under Section 232.", "url": "https://www.congress.gov/crs-product/IN12545", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "25%", "effective_date": "2025"}}]}, {"pair_id": "conflict_a33076fac697e33f8f7acbd3", "claim_ids": ["claim_be80e0e934ad712be5671a82", "claim_cb8d0b34638cb1159453a307"], "query_ids": ["q_447"], "claims": [{"claim_id": "claim_be80e0e934ad712be5671a82", "quote": "Under a U.S. deal with the United Kingdom (UK), most UK auto imports face a 10% total U.S. tariff rate.", "url": "https://www.congress.gov/crs-product/IN12545", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "U.S. deal with the United Kingdom", "duty_rate": "10%"}}, {"claim_id": "claim_cb8d0b34638cb1159453a307", "quote": "The United States has reached deals with other partners; for example, auto imports from the EU, Japan, and South Korea face a 15% total", "url": "https://www.congress.gov/crs-product/IN12545", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "15%"}}]}, {"pair_id": "conflict_23733d2c2687a77d2ca23694", "claim_ids": ["claim_10a5b29a1717137ebed46c65", "claim_66e8cba0b297ce63d139c3ea"], "query_ids": ["q_448"], "claims": [{"claim_id": "claim_10a5b29a1717137ebed46c65", "quote": "USMCA-compliant automobile parts will remain tariff-free until the Secretary of Commerce, in consultation with U.S. Customs and Border Protection (CBP), establishes a process to apply tariffs to their non-U.S. content.", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "USMCA"}}, {"claim_id": "claim_66e8cba0b297ce63d139c3ea", "quote": "Today, President Donald J. Trump signed a proclamation invoking Section 232 of the Trade Expansion Act of 1962 to impose a 25% tariff on imports of automobiles and certain automobile parts", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232 of the Trade Expansion Act of 1962", "duty_rate": "25%", "announcement_date": "Today", "reported_policy_status": "signed a proclamation"}}]}, {"pair_id": "conflict_1d8cb73bcabcb27909e5ebeb", "claim_ids": ["claim_1d3c0463abe24d8798e50739", "claim_2a30503b1002b59ad8290200"], "query_ids": ["q_448"], "claims": [{"claim_id": "claim_1d3c0463abe24d8798e50739", "quote": "Importers of automobiles under the United States-Mexico-Canada Agreement will be given the opportunity to certify their U.S. content and systems will be implemented such that the 25% tariff will only apply to the value of their non-U.S. content.", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "United States-Mexico-Canada Agreement"}}, {"claim_id": "claim_2a30503b1002b59ad8290200", "quote": "The 25% tariff will be applied to imported passenger vehicles (sedans, SUVs, crossovers, minivans, cargo vans) and light trucks, as well as key automobile parts (engines, transmissions, powertrain parts, and electrical components)", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "imported passenger vehicles (sedans, SUVs, crossovers, minivans, cargo vans) and light trucks, as well as key automobile parts (engines, transmissions, powertrain parts, and electrical components)", "duty_rate": "25%"}}]}, {"pair_id": "conflict_73390652833b51f737c9759e", "claim_ids": ["claim_2dcb9593e8bccfc0ad5757f0", "claim_3da010556c81cd6cb386b12c"], "query_ids": ["q_448"], "claims": [{"claim_id": "claim_2dcb9593e8bccfc0ad5757f0", "quote": "The Proclamation provides that automobile producers (i.e., OEMs) that perform final assembly of passenger vehicles and light trucks in the United States will be eligible for an “import adjustment offset” amount applicable to section 232 duties for automobile parts.", "url": "https://www.thompsonhinesmartrade.com/2025/04/white-house-amends-automobile-parts-tariffs-to-ease-burden-on-u-s-automakers", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "section 232 duties for automobile parts", "legal_authority": "The Proclamation", "affected_product": "passenger vehicles and light trucks"}}, {"claim_id": "claim_3da010556c81cd6cb386b12c", "quote": "Specifically, these credits will be available to OEMs in an amount equal to 3.75 percent of the aggregate Manufacturer’s Suggested Retail Price (MSRP) value of all in-scope automobiles assembled in the United States by that", "url": "https://www.thompsonhinesmartrade.com/2025/04/white-house-amends-automobile-parts-tariffs-to-ease-burden-on-u-s-automakers", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "3.75 percent"}}]}, {"pair_id": "conflict_5a3eff5534fbdf6cb1ce5bb3", "claim_ids": ["claim_3da010556c81cd6cb386b12c", "claim_c3ad754cabf7b5846920b84e"], "query_ids": ["q_448"], "claims": [{"claim_id": "claim_3da010556c81cd6cb386b12c", "quote": "Specifically, these credits will be available to OEMs in an amount equal to 3.75 percent of the aggregate Manufacturer’s Suggested Retail Price (MSRP) value of all in-scope automobiles assembled in the United States by that", "url": "https://www.thompsonhinesmartrade.com/2025/04/white-house-amends-automobile-parts-tariffs-to-ease-burden-on-u-s-automakers", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "3.75 percent"}}, {"claim_id": "claim_c3ad754cabf7b5846920b84e", "quote": "OEMs will be eligible to receive 2.5 percent of the aggregate MSRP value. These percentages reflect the total duty that would be owed when a 25 percent duty is applied to parts accounting 15% (2025-26) and 10% (2026-27) of the automobile’s MSRP value, respectively.", "url": "https://www.thompsonhinesmartrade.com/2025/04/white-house-amends-automobile-parts-tariffs-to-ease-burden-on-u-s-automakers", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "section 232 duties for automobile parts", "duty_rate": "25 percent", "effective_date": "April 3, 2025", "expiration_date": "April 30, 2026"}}]}, {"pair_id": "conflict_a3b3ea1e98f6a7dcd4c6fec3", "claim_ids": ["claim_1d3c0463abe24d8798e50739", "claim_5ebe3a12688f84cd74759afa"], "query_ids": ["q_448"], "claims": [{"claim_id": "claim_1d3c0463abe24d8798e50739", "quote": "Importers of automobiles under the United States-Mexico-Canada Agreement will be given the opportunity to certify their U.S. content and systems will be implemented such that the 25% tariff will only apply to the value of their non-U.S. content.", "url": "https://www.whitehouse.gov/fact-sheets/2025/03/fact-sheet-president-donald-j-trump-adjusts-imports-of-automobiles-and-automobile-parts-into-the-united-states", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "United States-Mexico-Canada Agreement"}}, {"claim_id": "claim_5ebe3a12688f84cd74759afa", "quote": "will provide the Secretary of Commerce with documentation as to the amount of U.S. content, and the 25% percent tariffs will only apply to the non-U.S. content in the automobile.", "url": "https://www.thompsonhinesmartrade.com/2025/04/white-house-amends-automobile-parts-tariffs-to-ease-burden-on-u-s-automakers", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25% percent"}}]}, {"pair_id": "conflict_efce99ace68664b2c44e79d6", "claim_ids": ["claim_85870720dd041507ba4d4d39", "claim_a46c5248a7d6bbd1804050c6"], "query_ids": ["q_449"], "claims": [{"claim_id": "claim_85870720dd041507ba4d4d39", "quote": "Presidential Proclamation 10908, \"Adjusting Imports of Automobiles and Certain Automobile Parts Into the United States,\" March 2025. Imposed a 25% tariff on passenger vehicles under HTS heading 8703, effective April 3, 2025.", "url": "https://gingercontrol.com/blog/hts-classification-auto-parts", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"legal_authority": "Presidential Proclamation 10908", "duty_rate": "25%"}}, {"claim_id": "claim_a46c5248a7d6bbd1804050c6", "quote": "Presidential Proclamation 10908 (effective April 3, 2025) imposed a 25% tariff on passenger vehicles classified under HTS heading 8703", "url": "https://gingercontrol.com/blog/hts-classification-auto-parts", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 Auto Parts Tariff", "legal_authority": "Trade Expansion Act of 1962", "duty_rate": "25%", "effective_date": "April 3, 2025", "reported_policy_status": "imposed"}}]}]}

